    25	
    26	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
    27	  return typeof response === 'string' ? {result: response} : response;
    28	}
    29	
    30	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
    31	
    32	export interface RegisteredTool {
    33	  definition: ToolDefinition;
    34	  execute: ToolExecutor;
    35	}
    36	
    37	interface StoredTool {
    38	  definitionSource: ToolDefinitionSource;
    39	  execute: ToolExecutor;
    40	  validate?: ValidateFunction;
    41	}
    42	
    43	// Kept in a variable so the literal skips excess-property checks against ajv Options.
    44	const AJV_OPTIONS = {strict: false, validateFormats: false, coerceTypes: false, useDefaults: false};
    45	const ajv = new Ajv(AJV_OPTIONS);
    46	const compiledBySchema = new WeakMap<object, ValidateFunction>();
    47	
    48	function compileSchema(toolName: string, schema: object): ValidateFunction {
    49	  const cached = compiledBySchema.get(schema);
    50	  if (cached) return cached;
    51	  let validate: ValidateFunction;
    52	  try {
    53	    validate = ajv.compile(schema);
    54	  } catch (error) {
    55	    throw new Error(`Invalid inputSchema for tool ${toolName}: ${(error as Error).message}`, {cause: error});
    56	  }
    57	  compiledBySchema.set(schema, validate);
    58	  return validate;
    59	}
    60	
    61	// Names the property path and the failed constraint only; never the offending value.
    62	function describeError(error: ErrorObject): string {
    63	  const at = error.instancePath || 'input';
    64	  const params = error.params as Record<string, unknown>;
    65	  switch (error.keyword) {
    66	    case 'required':
    67	      return `${at} is missing required property '${String(params.missingProperty)}'`;
    68	    case 'type':
    69	      return `${at} must be ${String(params.type)}`;
    70	    case 'enum':
    71	      return `${at} must be one of ${JSON.stringify(params.allowedValues)}`;
    72	    default:
    73	      return `${at} ${error.message ?? 'is invalid'}`;
    74	  }
    75	}
