    78	  private readonly tools = new Map<string, StoredTool>();
    79	
    80	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    81	    return typeof source === 'function' ? source() : source;
    82	  }
    83	
    84	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    85	    const resolved = this.resolveDefinition(definition);
    86	    const validate = typeof definition === 'function' ? undefined : compileSchema(resolved.name, resolved.inputSchema);
    87	    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
    88	  }
    89	
    90	  get(name: string): RegisteredTool | undefined {
    91	    const tool = this.tools.get(name);
    92	    if (!tool) return undefined;
    93	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
    94	  }
    95	
    96	  getDefinitions(): ToolDefinition[] {
    97	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
    98	  }
    99	
   100	  getPromptInstructions(): string[] {
   101	    return this.getDefinitions()
   102	      .filter(t => t.promptInstructions)
   103	      .map(t => `${t.name}: ${t.promptInstructions}`);
   104	  }
   105	
   106	  getExamplePrompts(): string[] {
   107	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
   108	  }
   109	
   110	  has(name: string): boolean {
   111	    return this.tools.has(name);
   112	  }
   113	
   114	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
   115	    const tool = this.tools.get(name);
   116	    if (!tool) {
   117	      log.warn('tool', 'tool not found', {name});
   118	      throw new Error(`Unknown tool: ${name}`);
   119	    }
   120	    const validate = tool.validate ?? compileSchema(name, this.resolveDefinition(tool.definitionSource).inputSchema);
   121	    if (!validate(input)) {
   122	      const result = `Invalid input for tool ${name}: ${(validate.errors ?? []).map(describeError).join('; ')}`;
   123	      log.warn('tool', 'input rejected', {name, reason: result});
   124	      return {result};
   125	    }
   126	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
   127	    const rawResult = await tool.execute(input, context);
   128	    const response = normalizeToolResponse(rawResult);
   129	    log.info('tool', 'execution complete', {
   130	      name,
   131	      rawType: typeof rawResult,
   132	      clientMessageCount: response.clientMessages?.length ?? 0,
   133	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
   134	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
   135	    });
   136	    return response;
   137	  }
   138	}
# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
